questionvariables.text:
/* Randomly select the logarithm base */
b: rand([2,3,5]);

/* Randomly select the intended integer solution */
k: rand([2,3,4,5,6]);

/* Randomly select a positive constant */
c: rand([1,2,3]);

/* Calculate a so that x = k is the solution */
a: (2*b-1)*k-b*c;

/* Set the correct answer */
ans: k;
